        public void ApplyCornerRadiusExperiment()
        {
            try
            {
                double px = SettingsService.Current.DesignExperimentCornerRadius;
                if (px <= 4.0) px = 12;   // 4 was the old default: it now means the standard card radius
                System.Windows.Application.Current.Resources["RadiusCard"] = new CornerRadius(px);
                System.Windows.Application.Current.Resources["RadiusCardTop"] = new CornerRadius(px, px, 0, 0);
                System.Windows.Application.Current.Resources["RadiusCardD"] = px;
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyCornerRadiusExperiment: {ex.Message}"); }
        }

        public void ApplyShadowExperiment()
        {
            try
            {
                bool off = SettingsService.Current.DesignExperimentShadowsOff;
                System.Windows.Application.Current.Resources["CardShadowEffect"] = off
                    ? new System.Windows.Media.Effects.DropShadowEffect { Opacity = 0 }
                    : new System.Windows.Media.Effects.DropShadowEffect
                      {
                          BlurRadius = 10, ShadowDepth = 1, Direction = 270,
                          Color = System.Windows.Media.Color.FromRgb(0, 0, 0), Opacity = 0.20,
                          RenderingBias = System.Windows.Media.Effects.RenderingBias.Performance,
                      };
                System.Windows.Application.Current.Resources["CardHoverShadowEffect"] = off
                    ? new System.Windows.Media.Effects.DropShadowEffect { Opacity = 0 }
                    : new System.Windows.Media.Effects.DropShadowEffect
                      {
                          BlurRadius = 14, ShadowDepth = 2, Direction = 270,
                          Color = System.Windows.Media.Color.FromArgb(0x40, 0, 0, 0), Opacity = 0.16,
                          RenderingBias = System.Windows.Media.Effects.RenderingBias.Performance,
                      };
                System.Windows.Application.Current.Resources["DashCardRestShadowEffect"] = off
                    ? new System.Windows.Media.Effects.DropShadowEffect { Opacity = 0 }
                    : new System.Windows.Media.Effects.DropShadowEffect
                      {
                          BlurRadius = 24, ShadowDepth = 2, Direction = 270,
                          Color = System.Windows.Media.Color.FromRgb(0, 0, 0), Opacity = 0.10,
                          RenderingBias = System.Windows.Media.Effects.RenderingBias.Performance,
                      };
                var res = System.Windows.Application.Current.Resources;
                res["CardHoverBg"] = off ? res["BgCardBrush"] : res["BgHoverBrush"];
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyShadowExperiment: {ex.Message}"); }
        }

        public void ApplySelectedButtonStyleExperiment()
        {
            try
            {
                int id = SettingsService.Current.SelectedButtonStyleId;
                var accentBrushObj = System.Windows.Application.Current.Resources["AccentBrush"];
                var accentColor = (accentBrushObj as System.Windows.Media.SolidColorBrush)?.Color
                                   ?? System.Windows.Media.Color.FromRgb(0x3B, 0x82, 0xF6);
                var accentBrush = new System.Windows.Media.SolidColorBrush(accentColor);
                var res = System.Windows.Application.Current.Resources;

                switch (id)
                {
                    case 6: // raised pill: a lighter background than the surrounding buttons, a very fine outline, normal text
                        res["SelBtnBg"] = res["SegOnBrush"] ?? accentBrush;
                        res["SelBtnFg"] = res["TextPrimaryBrush"] ?? System.Windows.Media.Brushes.White;
                        res["SelBtnBorderBrush"] = res["SelBorderBrush"] ?? System.Windows.Media.Brushes.Transparent;
                        res["SelBtnBorderThickness"] = new Thickness(1);
                        res["SelBtnCornerRadius"] = (res["RadiusControl"] as CornerRadius?) ?? new CornerRadius(4);
                        {
                            // no shadow: an effect on a button with text renders the text blurry; the lighter
                            // background and the fine outline mark the chosen pill
                            res["SelBtnEffect"] = null;
                        }
                        break;
                    default:
                    case 0: // Solid fill
                        res["SelBtnBg"] = accentBrush;
                        res["SelBtnFg"] = System.Windows.Media.Brushes.White;
                        res["SelBtnBorderBrush"] = accentBrush;
                        res["SelBtnBorderThickness"] = new Thickness(1);
                        res["SelBtnCornerRadius"] = (res["RadiusControl"] as CornerRadius?) ?? new CornerRadius(4);
                        res["SelBtnEffect"] = null;
                        break;
                    case 1: // Colored border
                        res["SelBtnBg"] = System.Windows.Media.Brushes.Transparent;
                        res["SelBtnFg"] = accentBrush;
                        res["SelBtnBorderBrush"] = accentBrush;
                        res["SelBtnBorderThickness"] = new Thickness(1);
                        res["SelBtnCornerRadius"] = (res["RadiusControl"] as CornerRadius?) ?? new CornerRadius(4);
                        res["SelBtnEffect"] = null;
                        break;
                    case 2: // Accent glow — a colour, not black, so it shows on Light too
                        res["SelBtnBg"] = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(28, accentColor.R, accentColor.G, accentColor.B));
                        res["SelBtnFg"] = accentBrush;
                        res["SelBtnBorderBrush"] = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(90, accentColor.R, accentColor.G, accentColor.B));
                        res["SelBtnBorderThickness"] = new Thickness(1);
                        res["SelBtnCornerRadius"] = (res["RadiusControl"] as CornerRadius?) ?? new CornerRadius(4);
                        res["SelBtnEffect"] = null;   // a glow on a button with text blurs the text
                        break;
                    case 3: // Underline
                        res["SelBtnBg"] = System.Windows.Media.Brushes.Transparent;
                        res["SelBtnFg"] = accentBrush;
                        res["SelBtnBorderBrush"] = accentBrush;
                        res["SelBtnBorderThickness"] = new Thickness(0, 0, 0, 2);
                        res["SelBtnCornerRadius"] = new CornerRadius(0);
                        res["SelBtnEffect"] = null;
                        break;
                    case 4: // Left stripe
                        res["SelBtnBg"] = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(22, accentColor.R, accentColor.G, accentColor.B));
                        res["SelBtnFg"] = accentBrush;
                        res["SelBtnBorderBrush"] = accentBrush;
                        res["SelBtnBorderThickness"] = new Thickness(3, 0, 0, 0);
                        res["SelBtnCornerRadius"] = new CornerRadius(0, 4, 4, 0);
                        res["SelBtnEffect"] = null;
                        break;
                    case 5:
                        // No border, no shadow — only a discreet tinted background. Works equally well whether or not the unselected button
                        // has a border, because it does not rely on a comparison with a "borderless" state.
                        res["SelBtnBg"] = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(32, accentColor.R, accentColor.G, accentColor.B));
                        res["SelBtnFg"] = accentBrush;
                        res["SelBtnBorderBrush"] = System.Windows.Media.Brushes.Transparent;
                        res["SelBtnBorderThickness"] = new Thickness(0);
                        res["SelBtnCornerRadius"] = (res["RadiusControl"] as CornerRadius?) ?? new CornerRadius(4);
                        res["SelBtnEffect"] = null;
                        break;
                }

                // Used directly in code (not through a Style) — Power Profile, the Disk Activity time windows, the day chips in the
                // Battery Report.
                RefreshManualSelectedButtons();
            }
            catch (Exception ex) { AppLogger.Debug($"ApplySelectedButtonStyleExperiment: {ex.Message}"); }
        }

        // Re-applies the "selected" state on the elements that do not go through a Style (they read the resources directly on
        // every redraw) — called after any style change in the Dev Panel, so they update without waiting for the next click.
        private void RefreshManualSelectedButtons()
        {
            try { LoadActivePowerPlan(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { RefreshDiskWindowButtonsStyle(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { RefreshProcessTabStyle(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { HighlightActiveThemeButton(SettingsService.Current.ThemeName, SettingsService.Current.AutoTheme); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { RefreshChartRangeButtonStyle(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        private void RefreshProcessTabStyle()
        {
            switch (_currentProcTab)
            {
                case "apps":       SetTabButtonStyles(BtnTabApps, BtnTabBackground, BtnTabAll); break;
                case "background": SetTabButtonStyles(BtnTabBackground, BtnTabApps, BtnTabAll); break;
                default:           SetTabButtonStyles(BtnTabAll, BtnTabApps, BtnTabBackground); break;
            }
        }

        private void RefreshChartRangeButtonStyle()
        {
            Border? active = _stressChartRangeSeconds switch
            {
                300  => BtnChartRange5m,
                900  => BtnChartRange15m,
                3600 => BtnChartRange1h,
                _    => BtnChartRange1m,
            };
            if (active == null) return;
            var res = System.Windows.Application.Current.Resources;
            foreach (var b in new[] { BtnChartRange1m, BtnChartRange5m, BtnChartRange15m, BtnChartRange1h })
            {
                if (b == null) continue;
                ApplySegmentLook(b, b == active);
            }
            UpdateStressRangeButton();
        }

        public void ApplySidebarRailExperiment()
        {
            try
            {
                bool on = SettingsService.Current.SidebarRailEnabled;
                System.Windows.Application.Current.Resources["SidebarRailVisibility"] =
                    on ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            }
            catch (Exception ex) { AppLogger.Debug($"ApplySidebarRailExperiment: {ex.Message}"); }
        }

        public void ApplyGrainTextureExperiment()
        {
            try
            {
                if (FindName("GrainTextureOverlay") is System.Windows.Shapes.Rectangle r)
                    r.Visibility = SettingsService.Current.DesignExperimentGrainTexture ? Visibility.Visible : Visibility.Collapsed;
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyGrainTextureExperiment: {ex.Message}"); }
        }

        public void ApplySignatureMotifExperiment()
        {
            try
            {
                bool on = SettingsService.Current.DesignExperimentSignatureMotif;
                foreach (var name in new[] { "SignatureMarkMemory", "SignatureMarkGpu" })
                {
                    if (FindName(name) is System.Windows.Controls.Canvas c)
                    {
                        c.Children.Clear();
                        if (on)
                        {
                            c.Children.Add(SMDWin.Services.SidebarAnimationLibrary.BuildSignatureMarkStatic());
                            c.Visibility = Visibility.Visible;
                        }
                        else c.Visibility = Visibility.Collapsed;
                    }
                }
            }
            catch (Exception ex) { AppLogger.Debug($"ApplySignatureMotifExperiment: {ex.Message}"); }
        }

        public void ApplyDesignExperimentFont()
        {
            try
            {
                bool mono = SettingsService.Current.DesignExperimentMonoNumbers;
                System.Windows.Application.Current.Resources["MonoFont"] = mono
                    ? new System.Windows.Media.FontFamily("Cascadia Mono, Consolas, Courier New")
                    : (System.Windows.Media.FontFamily)System.Windows.Application.Current.Resources["AppFont"];
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyDesignExperimentFont: {ex.Message}"); }
        }

        public void ApplySidebarAnimation()
